   340	func statusField(status, label string) string {
   341		for _, line := range strings.Split(status, "\n") {
   342			line = strings.TrimSpace(line)
   343			if rest, ok := strings.CutPrefix(line, label); ok {
   344				if fields := strings.Fields(rest); len(fields) > 0 {
   345					return fields[0]
   346				}
   347			}
   348		}
   349		return ""
