   351	
   352	// statusHandle pulls the @handle from the "User:" line. The line leads with
   353	// the account's DISPLAY NAME when one is set — "User: John Doe @john-doe
   354	// <mail>" — so the first field is a person's first name, not an identifier;
   355	// taking it builds an invalid (and wrong) project name like forgemark-John.
   356	// The handle is the @-prefixed field wherever it sits; fall back to the
   357	// first field for a bare "User: handle" shape.
   358	func statusHandle(status string) string {
   359		for _, line := range strings.Split(status, "\n") {
   360			rest, ok := strings.CutPrefix(strings.TrimSpace(line), "User:")
   361			if !ok {
   362				continue
   363			}
   364			fields := strings.Fields(rest)
   365			for _, f := range fields {
